<?php require APP_PATH.'Views/layouts/header.php';require APP_PATH.'Views/layouts/sidebar.php';$isAdmin=$is_admin??Auth::isAdmin();$tone=['Submitted'=>'warning','Under Review'=>'info','Approved'=>'success','Rejected'=>'danger','Processing'=>'info','Clearance Ongoing'=>'primary','Completed'=>'success','Cancelled'=>'secondary'];?>
<div id="main-content"><?php require APP_PATH.'Views/layouts/navbar.php';?>
<div class="page-command-bar my-3"><div class="page-command-title"><span class="scope-icon"><i class="fa-solid fa-person-walking-arrow-right"></i></span><div><strong>Separation &amp; Exit Clearance</strong><small><?=$isAdmin?'Review requests and manage complete offboarding':'Submit and track your separation and clearance'?></small></div></div><?php if(!$isAdmin):?><button class="btn btn-primary btn-sm" data-bs-toggle="modal" data-bs-target="#requestModal"><i class="fa-solid fa-plus"></i> Submit Separation Request</button><?php endif;?></div>
<div class="glass-card p-4" id="separationRecordsSection"><div class="d-flex justify-content-between align-items-center mb-3"><div><h5 class="fw-bold mb-0"><?=$isAdmin?'All Separation Requests':'My Separation Requests'?></h5><small class="text-secondary">Working dates, decisions and clearance progress</small></div><select id="statusFilter" class="form-select form-select-sm" style="max-width:190px"><option value="">All statuses</option><?php foreach(array_keys($tone) as $s):?><option><?=$s?></option><?php endforeach;?></select></div><div class="table-responsive"><table class="table align-middle" id="separationTable"><thead><tr><?php if($isAdmin):?><th>Employee</th><?php endif;?><th>Type / Filed</th><th>Working date</th><th>Status</th><th>Clearance</th><th>Remarks</th><th>Actions</th></tr></thead><tbody><?php foreach($separations as $s):?><?php $percent=$s['clearance_total']?(int)round($s['clearance_cleared']/$s['clearance_total']*100):0;?><tr><?php if($isAdmin):?><td><strong><?=htmlspecialchars($s['first_name'].' '.$s['last_name'])?></strong><br><small><?=htmlspecialchars($s['employee_code'].' · '.($s['department_name']??''))?></small></td><?php endif;?><td><strong><?=htmlspecialchars($s['separation_type'])?></strong><br><small><?=date('M j, Y',strtotime($s['created_at']))?></small></td><td>Proposed: <?=htmlspecialchars($s['proposed_last_working_date']?:$s['effective_date'])?><br><small>Confirmed: <?=htmlspecialchars($s['final_working_date']?:'—')?></small></td><td><span class="badge badge-soft-<?=$tone[$s['status']]??'secondary'?>"><?=$s['status']?></span><?php if($s['archived_at']):?><br><small>Archived</small><?php endif;?></td><td><div class="progress" style="width:110px;height:7px"><div class="progress-bar" style="width:<?=$percent?>%"></div></div><small><?=$s['clearance_cleared']?>/<?=$s['clearance_total']?> cleared</small></td><td><?php if(!empty($s['employee_remarks'])):?><small class="d-block"><strong>Employee:</strong> <?=htmlspecialchars($s['employee_remarks'])?></small><?php endif;?><?php if(!empty($s['admin_remarks'])):?><small class="d-block"><strong>Admin:</strong> <?=htmlspecialchars($s['admin_remarks'])?></small><?php endif;?><?php if(empty($s['employee_remarks'])&&empty($s['admin_remarks'])):?><small>—</small><?php endif;?></td><td><div class="d-flex gap-1 flex-wrap"><a class="btn btn-outline-primary btn-sm" href="index.php?page=separation_clearance&id=<?=$s['id']?>">View</a><?php if($s['resignation_file']):?><a class="btn btn-outline-secondary btn-sm" href="index.php?page=separation_file&kind=resignation&id=<?=$s['id']?>">Letter</a><?php endif;?><?php if($isAdmin&&in_array($s['status'],['Submitted','Under Review','Approved'],true)):?><button class="btn btn-primary btn-sm review-separation" data-json='<?=htmlspecialchars(json_encode($s),ENT_QUOTES)?>'>Process</button><?php endif;?><?php if($isAdmin&&$s['status']==='Processing'):?><button class="btn btn-success btn-sm generate-clearance" data-id="<?=$s['id']?>">Create Clearance</button><?php endif;?><?php if($s['status']==='Completed'):?><a class="btn btn-success btn-sm" href="index.php?page=separation_final_clearance&id=<?=$s['id']?>">Final Clearance</a><?php if($isAdmin&&!$s['archived_at']):?><button class="btn btn-outline-secondary btn-sm archive-separation" data-id="<?=$s['id']?>">Archive</button><?php endif;?><?php endif;?></div></td></tr><?php endforeach;?></tbody></table></div><?php if(!$separations):?><div class="text-center py-5 text-secondary"><i class="fa-solid fa-user-check fa-2x mb-2"></i><p>No separation requests found.</p></div><?php endif;?></div></div>
<?php if(!$isAdmin):?><div class="modal fade" id="requestModal"><div class="modal-dialog"><form class="modal-content" id="requestForm" enctype="multipart/form-data"><div class="modal-header"><h5>Submit Separation Request</h5><button class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><?=csrf_input()?><label class="form-label">Separation type</label><select name="separation_type" class="form-select mb-3" required><option>Resignation</option><option>End of Contract</option><option>Retirement</option><option>Termination</option><option>Other</option></select><label class="form-label">Proposed last working date</label><input type="date" name="proposed_last_working_date" class="form-control mb-3" min="<?=date('Y-m-d')?>" required><label class="form-label">Reason</label><textarea name="reason" class="form-control mb-3" required></textarea><label class="form-label">Additional remarks <span class="text-secondary fw-normal">(optional)</span></label><textarea name="employee_remarks" class="form-control mb-3" maxlength="2000" rows="3" placeholder="Add any information HR should consider"></textarea><label class="form-label">Resignation/separation letter (PDF/JPG/PNG, 5 MB)</label><input type="file" name="resignation_letter" class="form-control" accept=".pdf,.jpg,.jpeg,.png" required></div><div class="modal-footer"><button class="btn btn-primary">Submit Request</button></div></form></div></div><?php endif;?>
<?php if($isAdmin):?><div class="modal fade" id="reviewModal"><div class="modal-dialog"><form class="modal-content" id="reviewForm"><div class="modal-header"><h5>Review Separation Request</h5><button class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><?=csrf_input()?><input type="hidden" name="id" id="reviewId"><div class="alert alert-info" id="reviewSummary"></div><label class="form-label">Next status</label><select name="status" id="reviewStatus" class="form-select mb-3"></select><label class="form-label">Confirmed final working date</label><input type="date" name="final_working_date" id="finalWorkingDate" class="form-control mb-3"><label class="form-label">Admin remarks</label><textarea name="admin_remarks" class="form-control"></textarea></div><div class="modal-footer"><button class="btn btn-primary">Save Decision</button></div></form></div></div><?php endif;?>
<?php require APP_PATH.'Views/layouts/footer.php';?>
<script>$(function(){const csrf='<?=csrf_token()?>',post=(url,data,fd=false)=>$.ajax({url,type:'POST',data,processData:!fd,contentType:fd?false:'application/x-www-form-urlencoded',dataType:'json'}).done(r=>{if(r.status==='success'){showToast('success',r.message);setTimeout(()=>location.reload(),700)}else Swal.fire('Error',r.message,'error')}).fail(x=>Swal.fire('Error',x.responseJSON?.message||'Request failed.','error'));let table=$('#separationTable').DataTable({pageLength:10});$('#statusFilter').change(function(){table.column(<?=$isAdmin?3:2?>).search(this.value).draw()});$('#requestForm').submit(function(e){e.preventDefault();post('index.php?page=separation_initiate',new FormData(this),true)});const transitions={'Submitted':['Under Review','Approved','Rejected','Cancelled'],'Under Review':['Approved','Rejected','Cancelled'],'Approved':['Processing','Cancelled']};$('.review-separation').click(function(){let s=$(this).data('json');$('#reviewId').val(s.id);$('#reviewSummary').text(s.first_name+' '+s.last_name+' · '+s.separation_type+' · Proposed '+s.proposed_last_working_date);$('#finalWorkingDate').val(s.final_working_date||s.proposed_last_working_date);$('#reviewStatus').html((transitions[s.status]||[]).map(x=>`<option>${x}</option>`));bootstrap.Modal.getOrCreateInstance('#reviewModal').show()});$('#reviewForm').submit(function(e){e.preventDefault();post('index.php?page=separation_review',$(this).serialize())});$('.generate-clearance').click(function(){post('index.php?page=separation_generate_clearance',{id:$(this).data('id'),csrf_token:csrf})});$('.archive-separation').click(function(){post('index.php?page=separation_archive',{id:$(this).data('id'),csrf_token:csrf})})});</script>
